  "description": "Risk per dollar spent by a buyer.",
  "definition": "BRDR = \\frac{\\text{risk\\_score}}{\\text{total\\_spending\\_usd}}"
}

{
  "id": 29,
  "knowledge": "Spend Pattern Categories",
  "description": "Buyer spending trends.",
  "definition": "Values: High, Low, Medium, Variable.\nLabel descriptions:\n- High: Frequent, high value purchases indicative of heavy marketplace engagement.\n- Low: Infrequent, low value purchases typical of casual or opportunistic buyers.\n- Medium: Steady purchasing cadence with moderate transaction amounts.\n- Variable: Irregular bursts of spending with no predictable pattern."
}

